config.code:
// 兩個「打 API」步驟的輸出欄位名一模一樣(status/body/json)——所以這裡用「分開層」
// ctx.outputs 各自精準取值,不會拿錯(這正是平台處理同名欄位的標準寫法)。
const w = ctx.outputs?.["fetchWeather"]?.json;
const fxRes = ctx.outputs?.["fetchFx"]?.json;
if (!w || !w.daily) throw new Error("天氣資料不完整(daily 欄位不存在),請稍後再試");
if (!fxRes || !fxRes.rates || !fxRes.rates.TWD) throw new Error("匯率資料不完整(rates.TWD 不存在),請稍後再試");

const d = w.daily;
const fx = fxRes.rates;
const round2 = (n) => Math.round(n * 100) / 100;
const out = {
  日期: d.time[0],
  今天最高: d.temperature_2m_max[0], 今天最低: d.temperature_2m_min[0], 今天降雨: d.precipitation_probability_max[0],
  明天最高: d.temperature_2m_max[1], 明天最低: d.temperature_2m_min[1], 明天降雨: d.precipitation_probability_max[1],
  美元台幣: round2(fx.TWD),
  日圓台幣: round2(fx.TWD / fx.JPY),
};
ctx.log(`今天 ${out.今天最低}–${out.今天最高}°C 降雨 ${out.今天降雨}%;美元 ${out.美元台幣}、日圓 ${out.日圓台幣}`);
return { ...ctx.input, ...out };

